import org.apache.commons.math3.distribution.EnumeratedIntegerDistribution;
import java.util.Arrays;

public class Main {
  public static void main(String[] args) {
      // En Java corporativo se usa EnumeratedDistribution de Commons Math:
      int[] valores = {3, 5, 7, 9};
      double[] probabilidades = {0.1, 0.3, 0.6, 0.0};

      EnumeratedIntegerDistribution dist = 
              new EnumeratedIntegerDistribution(valores, probabilidades);

      // Generar 100 muestras
      int[] muestras = dist.sample(100);
      System.out.println(Arrays.toString(muestras));
  }
}
